// Parse Claude's JSON response
const claudeResponse = $input.first().json.message.content[0].text;

// Try to extract JSON from response (in case Claude added explanation)
let jsonMatch = claudeResponse.match(/\{[\s\S]*\}/);
let extractedData;

if (jsonMatch) {
  extractedData = JSON.parse(jsonMatch[0]);
} else {
  throw new Error('Could not extract valid JSON from Claude response');
}

// Transform to array of products ready for database insertion
const products = extractedData.products.map(product => ({
  product_name: product.product_name.trim(),
  category: product.category || null,
  measurement_unit_name: product.measurement_unit_name.toUpperCase(),
  quantity: parseFloat(product.quantity) || 1,
  price_extra: product.price_extra ? parseFloat(product.price_extra) : null,
  price_first: product.price_first ? parseFloat(product.price_first) : null,
  price_unit: parseFloat(product.price_unit),
  price_variation: product.price_variation,
  date: extractedData.bulletin_date,
  source: extractedData.source || 'Corabastos',
  raw_name: product.raw_name || product.product_name
}));

// Add metadata
const output = {
  bulletin_date: extractedData.bulletin_date,
  total_products: products.length,
  extraction_timestamp: new Date().toISOString(),
  products: products
};

return [{ json: output }];

// Aggregate results from all insertions
const allItems = $input.all();

let successful = 0;
let failed = 0;
let failedProducts = [];

allItems.forEach(item => {
  const response = item.json;
  if (response.success === true) {
    successful++;
  } else {
    failed++;
    failedProducts.push({
      product: item.json.product_name || 'Unknown',
      error: response.message || 'Unknown error'
    });
  }
});

const summary = {
  ingestion_date: new Date().toISOString(),
  total_processed: allItems.length,
  successful_insertions: successful,
  failed_insertions: failed,
  success_rate: ((successful / allItems.length) * 100).toFixed(2) + '%',
  failed_products: failedProducts
};

return [{ json: summary }];

